"""Press scheduler for the Hollybush Cidery."""
import time

from press.limits import STUCK_POLLS, STUCK_POLL_SECONDS


def press(vat):
    """Press one vat, waiting while the vat has not cleared."""
    for _ in range(STUCK_POLLS):
        if vat.ready():
            return vat.press()
        time.sleep(STUCK_POLL_SECONDS)
    raise RuntimeError("vat stuck")


def press_all(vats):
    return [press(vat) for vat in vats]
